function TodoList() {
  const [todos, setTodos] = useState([
    { id: 'a', text: 'Buy milk' },
    { id: 'b', text: 'Walk dog' },
  ]);

  function addFirst() {
    setTodos([{ id: 'c', text: 'Wash dishes' }, ...todos]);
  }

  return (
    <div>
      <button onClick={addFirst}>Add to top</button>
      <ul>
        {todos.map((todo, index) => (
          <TodoRow key={index} todo={todo} />
        ))}
      </ul>
    </div>
  );
}

function TodoRow({ todo }: { todo: { id: string; text: string } }) {
  const [note, setNote] = useState('');
  return (
    <li>
      <span>{todo.text}</span>
      <input value={note} onChange={(e) => setNote(e.target.value)} placeholder="note" />
    </li>
  );
}

function AddComment({ postId }: { postId: string }) {
  const [comment, setComment] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [saving, setSaving] = useState(false);

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setSaving(true);
    setError(null);
    try {
      await saveComment(postId, comment);
      setComment('');
    } catch {
      setError('Could not save the comment');
    } finally {
      setSaving(false);
    }
  }

  return (
    <form onSubmit={handleSubmit}>
      <input name="comment" value={comment} onChange={(e) => setComment(e.target.value)} />
      <button disabled={saving}>{saving ? 'Saving...' : 'Add'}</button>
      {error && <p role="alert">{error}</p>}
    </form>
  );
}

scenarios.modelAnswer:
Refactored form:

type FormState = { error: string | null };

async function addComment(prev: FormState, formData: FormData): Promise<FormState> {
  const text = String(formData.get('comment') ?? '');
  const result = await saveComment(postId, text); // returns { error } or null
  return { error: result?.error ?? null };
}

function AddComment({ postId }: { postId: string }) {
  const [state, formAction, pending] = useActionState(addComment, { error: null });
  return (
    <form action={formAction}>
      <input name="comment" required />
      <button disabled={pending}>{pending ? 'Saving...' : 'Add'}</button>
      {state.error && <p role="alert">{state.error}</p>}
    </form>
  );
}

What React now owns: passing the form to `formAction` automatically wraps the submission in a transition, so no startTransition and no manual `saving` state; the hook's `pending` flag replaces it. The action receives `(previousState, formData)`, with previous state first, so each submission sees the result of the previous one and errors clear naturally on retry. Because the input is now uncontrolled and read via FormData, React resets the form automatically after a successful action, which reproduces 'clears only on success' for free: if the action throws, the reset does not happen. What you still own: server-side authorization and validation (the client `required` attribute is UX, not security), returning expected errors as state instead of throwing them into an error boundary, and the actual persistence. If the comment list should show the new comment immediately, `useOptimistic` can render the expected comment during the transition, and a deeply nested submit button could read the form's pending state with `useFormStatus` instead of receiving a prop. Sources: https://react.dev/reference/react/useActionState, https://react.dev/blog/2024/12/05/react-19#form-actions.
